/// <summary> Получает или устанавливает минимальный шаг цены </summary>
/// <param name="_tickSize"> Минимальный шаг изменения цены </param>
/// <returns> Минимальный шаг изменения цены </returns>
[DataMember('tickSize')]
public str parmTickSize(str _tickSize = tickSize)
{
    tickSize = _tickSize;
    return tickSize;
}

/// <summary> Получает или устанавливает минимальную цену </summary>
/// <param name="_minPrice"> Минимально допустимая цена </param>
/// <returns> Минимально допустимая цена </returns>
[DataMember('minPrice')]
public str parmMinPrice(str _minPrice = minPrice)
{
    minPrice = _minPrice;
    return minPrice;
}

/// <summary> Получает или устанавливает максимальную цену </summary>
/// <param name="_maxPrice"> Максимально допустимая цена </param>
/// <returns> Максимально допустимая цена </returns>
[DataMember('maxPrice')]
public str parmMaxPrice(str _maxPrice = maxPrice)
{
    maxPrice = _maxPrice;
    return maxPrice;
}
